function sampleSitePoints(place,count){const g=place?.geometry;if(!g)return[];const polygons=g.type==='Polygon'?[g.coordinates]:g.type==='MultiPolygon'?g.coordinates:[];const inRing=(lng,lat,ring)=>{let inside=false;for(let i=0,j=ring.length-1;i<ring.length;j=i++){const [xi,yi]=ring[i],[xj,yj]=ring[j];if(((yi>lat)!==(yj>lat))&&(lng<(xj-xi)*(lat-yi)/((yj-yi)||1e-12)+xi))inside=!inside}return inside};const inside=(lng,lat,poly)=>inRing(lng,lat,poly[0]||[])&&!poly.slice(1).some(r=>inRing(lng,lat,r));const rings=polygons.filter(p=>p[0]?.length>3);if(!rings.length)return[];let ring=rings[0][0];const bounds=ring.reduce((b,p)=>({minX:Math.min(b.minX,p[0]),maxX:Math.max(b.maxX,p[0]),minY:Math.min(b.minY,p[1]),maxY:Math.max(b.maxY,p[1])}),{minX:Infinity,maxX:-Infinity,minY:Infinity,maxY:-Infinity});const result=[];for(let i=1;i<3000&&result.length<count;i++){const u=(i*.61803398875)%1,v=(i*.75487766625)%1,lng=bounds.minX+(bounds.maxX-bounds.minX)*u,lat=bounds.minY+(bounds.maxY-bounds.minY)*v,poly=rings.find(p=>inside(lng,lat,p));if(poly&&!result.some(q=>Math.abs(q.lat-lat)<(bounds.maxY-bounds.minY)*.045&&Math.abs(q.lng-lng)<(bounds.maxX-bounds.minX)*.045))result.push({lat,lng})}return result}
