function photoMarkerIcon(){return L.divIcon({className:'',html:'<span class="photo-site-marker" aria-label="Geotagged photo"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7h3l1.5-2h7L17 7h3v12H4z"/><circle cx="12" cy="13" r="3.5"/></svg></span>',iconSize:[32,36],iconAnchor:[16,18]})}
function photoMatchesIntervention(photo,item){if(Number(photo.intervention_id)===Number(item.id))return true;const a=Number(photo.lat),b=Number(photo.lng),c=Number(item.lat),d=Number(item.lng);if(![a,b,c,d].every(Number.isFinite))return false;const rad=v=>v*Math.PI/180,dy=rad(c-a),dx=rad(d-b),q=Math.sin(dy/2)**2+Math.cos(rad(a))*Math.cos(rad(c))*Math.sin(dx/2)**2;return 6371000*2*Math.atan2(Math.sqrt(q),Math.sqrt(1-q))<=100}
function photosForIntervention(item){return photoData.filter(photo=>photoMatchesIntervention(photo,item))}
async function copyDetailValue(value,label){try{if(navigator.clipboard&&window.isSecureContext)await navigator.clipboard.writeText(value);else{const box=document.createElement('textarea');box.value=value;box.style.position='fixed';box.style.opacity='0';document.body.appendChild(box);box.select();const copied=document.execCommand('copy');box.remove();if(!copied)throw Error('Clipboard unavailable')}toast(`${label} copied.`)}catch{toast('Could not access clipboard. Select and copy the value instead.')}}
