function openIntervention(item){if(!item)return;activeIntervention=item;const lat=Number(item.lat),lng=Number(item.lng),photos=photosForIntervention(item),coords=Number.isFinite(lat)&&Number.isFinite(lng)?`${lat.toFixed(6)}, ${lng.toFixed(6)}`:'',fields=[['Site name',item.name],['Type',item.type],['Status',item.status],['Location',item.location],['Date',item.date],['Latitude',Number.isFinite(lat)?lat.toFixed(6):''],['Longitude',Number.isFinite(lng)?lng.toFixed(6):''],['Description',item.description],...(item.is_demo?[['Data note','Illustrative sample only; replace with a verified Coordinator record.']]:[])];const photoCard=photo=>`<article class="photo-card site-photo-card"><img src="/api/uploads/${encodeURIComponent(photo.filename)}" alt="${esc(photo.location)}"><div class="photo-meta"><strong>${esc(photo.location)}</strong>${esc(photo.taken_at||'Date not recorded')} · ${Number(photo.lat).toFixed(5)}, ${Number(photo.lng).toFixed(5)}${photo.description?`<br>${esc(photo.description)}`:''}</div></article>`;const phasePhotos=phase=>photos.filter(photo=>String(photo.phase||'').toLowerCase()===phase);const before=phasePhotos('before'),after=phasePhotos('after'),other=photos.filter(photo=>!['before','after'].includes(String(photo.phase||'').toLowerCase()));const stageGroup=(label,items,phase)=>`<section class="photo-stage-group"><h4>${label} <span>${items.length}</span></h4>${items.length?`<div class="site-photo-grid">${items.map(photoCard).join('')}</div>`:`<div class="site-no-photos">No ${label.toLowerCase()} photo uploaded for this site yet.</div>`}</section>`;const comparison=`<section class="site-photos-section"><h3>Before &amp; after photos <span>${before.length+after.length}</span></h3>${item.is_demo?'<p class="sample-disclaimer">Sample map site. Any uploaded photos shown here are real Coordinator photos; the sample illustrations fill only stages without a photo.</p>':''}<div class="site-photo-stage-groups">${item.is_demo?`<section class="photo-stage-group"><h4>Before <span>${before.length}</span></h4>${before.length?`<div class="site-photo-grid">${before.map(photoCard).join('')}</div>`:`<div class="sample-comparison"><article><img src="${sampleSceneSvg('before',item.sample_index||0)}" alt="Illustrative before condition"><b>Illustrative sample · Before</b></article></div>`}</section><section class="photo-stage-group"><h4>After <span>${after.length}</span></h4>${after.length?`<div class="site-photo-grid">${after.map(photoCard).join('')}</div>`:`<div class="sample-comparison"><article><img src="${sampleSceneSvg('after',item.sample_index||0)}" alt="Illustrative after condition"><b>Illustrative sample · After</b></article></div>`}</section>`:`${stageGroup('Before',before,'before')}${stageGroup('After',after,'after')}`}${other.length?`<section class="photo-stage-group"><h4>Progress / other <span>${other.length}</span></h4><div class="site-photo-grid">${other.map(photoCard).join('')}</div></section>`:''}</div></section>`;$('#modal-root').innerHTML=`<div class="quick-modal" id="quick-modal"><section class="quick-box site-detail-modal" role="dialog" aria-modal="true" aria-labelledby="site-detail-title"><button class="close" id="close-modal" aria-label="Close">×</button><div class="site-detail-heading"><span class="intervention-legend-icon large" style="--marker-color:${interventionColor(item.type)}">${interventionSymbolSvg(item.type)}</span><div>${item.is_demo?'<span class="status-badge sample-badge">Illustrative sample</span> ':''}<span class="status-badge">${esc(item.status||'Status not recorded')}</span><h2 id="site-detail-title">${esc(item.type)}</h2><div class="subtle">⌖ ${esc(item.location||'Location not recorded')}</div></div></div><section class="detail-card site-analysis-card"><h3>Analysis &amp; Intervention Details</h3><p class="muted">${esc(item.description||'No description recorded for this site.')}</p><div class="site-detail-grid"><div><span>Site</span><b>${esc(item.name||item.location||'Field site')}</b></div><div><span>Date</span><b>${esc(item.date||'Not recorded')}</b></div><div><span>GPS coordinates</span><b>${coords||'Not recorded'}</b></div><div><span>Uploaded photos</span><b>${photos.length}</b></div></div><div class="site-copy-actions">${item.location?`<button class="btn small" data-copy-value="${esc(item.location)}" data-copy-label="Location">Copy location</button>`:''}${coords?`<button class="btn small" data-copy-value="${coords}" data-copy-label="Coordinates">Copy coordinates</button>`:''}</div></section>${comparison}<button class="btn primary site-full-info" id="site-full-info" aria-expanded="false">⌖ &nbsp; Zoom to site &amp; show full info</button><section class="site-full-details hidden" id="site-full-details"><h3>Full Coordinator record</h3><div class="site-detail-grid full">${fields.filter(([,value])=>value!==null&&value!==undefined&&String(value).trim()!=='').map(([label,value])=>`<div><span>${esc(label)}</span><b>${esc(value)}</b></div>`).join('')}</div><a class="btn site-record-open" href="#${item.type==='Contour Trenching'?'trenching':'detail'}?id=${encodeURIComponent(item.id)}">Open full site page →</a></section></section></div>`;const close=()=>$('#modal-root').innerHTML='';$('#close-modal').onclick=close;$('#quick-modal').onclick=e=>{if(e.target.id==='quick-modal')close()};bindCopyButtons($('#quick-modal'));$('#site-full-info').onclick=e=>{const panel=$('#site-full-details'),expanded=panel.classList.toggle('hidden')===false;e.currentTarget.setAttribute('aria-expanded',String(expanded));e.currentTarget.innerHTML=expanded?'⌖ &nbsp; Hide full info':'⌖ &nbsp; Zoom to site &amp; show full info';if(Number.isFinite(lat)&&Number.isFinite(lng)&&map)map.setView([lat,lng],Math.max(map.getZoom(),14),{animate:true})}}
function openPhotoDetails(photo){if(!photo)return;const lat=Number(photo.lat),lng=Number(photo.lng);$('#modal-root').innerHTML=`<div class="quick-modal" id="quick-modal"><section class="quick-box site-detail-modal" role="dialog" aria-modal="true"><button class="close" id="close-modal" aria-label="Close">×</button><div class="site-detail-heading"><span class="photo-site-marker large">▣</span><div><span class="status-badge">Geotagged field photo</span><h2>${esc(photo.location)}</h2><div class="subtle">${esc(photo.taken_at||'Date not recorded')}</div></div></div><img class="site-photo-large" src="/api/uploads/${encodeURIComponent(photo.filename)}" alt="${esc(photo.description||photo.location)}"><p>${esc(photo.description||'No field notes recorded.')}</p><div class="site-detail-grid"><div><span>GPS coordinates</span><b>${Number.isFinite(lat)&&Number.isFinite(lng)?`${lat.toFixed(6)}, ${lng.toFixed(6)}`:'Not recorded'}</b></div><div><span>Linked intervention</span><b>${esc(photo.intervention||'No linked Coordinator site')}</b></div></div><button class="btn primary site-photo-zoom" id="site-photo-zoom">⌖ &nbsp; Zoom to photo location</button></section></div>`;const close=()=>$('#modal-root').innerHTML='';$('#close-modal').onclick=close;$('#quick-modal').onclick=e=>{if(e.target.id==='quick-modal')close()};$('#site-photo-zoom').onclick=()=>{if(Number.isFinite(lat)&&Number.isFinite(lng)&&map)map.setView([lat,lng],Math.max(map.getZoom(),15),{animate:true})}}
function detailPage(){const query=location.hash.includes('?')?location.hash.split('?').slice(1).join('?'):'',id=Number(new URLSearchParams(query).get('id')),item=activeIntervention&&Number(activeIntervention.id)===id?activeIntervention:interventions.find(x=>Number(x.id)===id)||activeIntervention;if(!item)return `<div class="page"><div class="app-shell">${rail('interventions')}<section class="content"><div class="panel"><div class="state">Choose an intervention symbol on the map to open its saved site record.</div><a class="btn primary" href="#interventions">Back to Watershed Intervention Map</a></div></section></div></div>`;activeIntervention=item;const lat=Number(item.lat),lng=Number(item.lng),photos=photosForIntervention(item),pairs=[['Location',item.location],['Status',item.status],['Implementation date',item.date],['Latitude',Number.isFinite(lat)?lat.toFixed(6):''],['Longitude',Number.isFinite(lng)?lng.toFixed(6):''],['Description',item.description]];return `<div class="page"><div class="app-shell">${rail('interventions')}<section class="content"><div class="site-page-nav"><a href="#interventions">‹ Back to Map</a><span class="status-badge">${esc(item.status||'Status not recorded')}</span><a class="btn small" href="#photos">▣ Upload Geotag Photos</a></div>${pageHead(item.type,esc(item.location||'Location not recorded'))}<section class="panel site-page-gallery-panel"><h3>Geotagged field photos</h3><div class="site-page-photos" id="site-record-photos">${photos.length?photos.map(photo=>`<article class="photo-card site-page-photo"><img src="/api/uploads/${encodeURIComponent(photo.filename)}" alt="${esc(photo.description||photo.location)}"><div class="photo-meta"><strong>${esc(photo.location)}</strong>${esc(photo.taken_at||'Date not recorded')} · ${Number(photo.lat).toFixed(6)}, ${Number(photo.lng).toFixed(6)}${photo.description?`<br>${esc(photo.description)}`:''}</div></article>`).join(''):'<div class="site-no-photos">No photos have been uploaded for this site or its coordinates.</div>'}</div><p class="muted site-photo-count" id="site-record-photo-count">${photos.length} saved photo${photos.length===1?'':'s'} at this site</p></section><div class="detail-sections site-page-sections"><section class="panel"><h3>Intervention Details</h3><div class="site-detail-grid full">${pairs.filter(([,value])=>value!==null&&value!==undefined&&String(value).trim()!=='').map(([label,value])=>`<div><span>${esc(label)}</span><b>${esc(value)}</b></div>`).join('')}</div></section><section class="panel"><h3>Key Parameters</h3><div class="site-no-photos">No measured parameters are recorded for this site yet.</div></section></div><section class="panel site-impact-note"><h3>Project Impact</h3><div class="site-no-photos">Impact measurements are not present in the saved Coordinator record.</div></section></section><aside class="right-column"><section class="panel"><h3>Site Information</h3><div class="site-info-symbol" style="--marker-color:${interventionColor(item.type)}">${interventionSymbolSvg(item.type)}</div><div class="info-row"><span>Intervention</span><b>${esc(item.type)}</b></div><div class="info-row"><span>Location</span><b>${esc(item.location||'Not recorded')}</b></div><div class="info-row"><span>Latitude / Longitude</span><b>${Number.isFinite(lat)&&Number.isFinite(lng)?`${lat.toFixed(6)}, ${lng.toFixed(6)}`:'Not recorded'}</b></div><div class="info-row"><span>Field photos</span><b id="site-record-photo-count-side">${photos.length}</b></div></section><section class="panel"><h3>Coordinator Record</h3>${pairs.filter(([,value])=>value!==null&&value!==undefined&&String(value).trim()!=='').map(([label,value])=>`<div class="info-row"><span>${esc(label)}</span><b>${esc(value)}</b></div>`).join('')}</section></aside></div></div>`}
async function loadSitePagePhotos(){if(!activeIntervention)return;try{const d=await api('/photos');photoData=d.items||[];const photos=photosForIntervention(activeIntervention),gallery=$('#site-record-photos');if(!gallery)return;gallery.innerHTML=photos.length?photos.map(photo=>`<article class="photo-card site-page-photo"><img src="/api/uploads/${encodeURIComponent(photo.filename)}" alt="${esc(photo.description||photo.location)}"><div class="photo-meta"><strong>${esc(photo.location)}</strong>${esc(photo.taken_at||'Date not recorded')} · ${Number(photo.lat).toFixed(6)}, ${Number(photo.lng).toFixed(6)}${photo.description?`<br>${esc(photo.description)}`:''}</div></article>`).join(''):'<div class="site-no-photos">No photos have been uploaded for this site or its coordinates.</div>';const count=$('#site-record-photo-count');if(count)count.textContent=`${photos.length} saved photo${photos.length===1?'':'s'} at this site`;const side=$('#site-record-photo-count-side');if(side)side.textContent=photos.length}catch(error){toast(error.message)}}

window.openInterventionById=id=>openIntervention(interventions.find(x=>x.id===id));
