function bindPhotoForm(){const form=$('#photo-form');if(!form)return;const input=$('#photo-file'),zone=$('#dropzone'),pasteTarget=$('#photo-paste-target'),submit=form.querySelector('[type=submit]'),status=$('#photo-upload-status'),interventionSelect=$('#photo-intervention');const show=(message,ok=false)=>{if(status){status.textContent=message;status.classList.remove('hidden','success-note');if(ok)status.classList.add('success-note')}};const setFile=file=>{if(!file)return false;const fileError=photoFileError(file);if(fileError){show(fileError);toast(fileError);return false}const normalized=normalizePhotoFile(file);const transfer=new DataTransfer();transfer.items.add(normalized);input.files=transfer.files;previewFile();show('Photo ready. Choose its stage and save the location.');return true};zone.addEventListener('click',e=>{if(e.target!==input)input.click()});input.addEventListener('change',()=>{let file=input.files[0],error=photoFileError(file);if(error){show(error);input.value='';return}file=normalizePhotoFile(file);if(file!==input.files[0]){const transfer=new DataTransfer();transfer.items.add(file);input.files=transfer.files}previewFile();show('Photo ready. Choose its stage and save the location.')});['dragenter','dragover'].forEach(t=>zone.addEventListener(t,e=>{e.preventDefault();zone.classList.add('drag')}));['dragleave','drop'].forEach(t=>zone.addEventListener(t,e=>{e.preventDefault();zone.classList.remove('drag')}));zone.addEventListener('drop',e=>{if(e.dataTransfer.files[0])setFile(e.dataTransfer.files[0])});pasteTarget?.addEventListener('click',()=>pasteTarget.focus());pasteTarget?.addEventListener('paste',e=>{const items=[...(e.clipboardData?.items||[])],item=items.find(x=>x.kind==='file'&&x.type.startsWith('image/'));if(!item){show('Clipboard has no image. Copy an image first, then paste here.');return}e.preventDefault();const file=item.getAsFile();if(file)setFile(file)});interventionSelect?.addEventListener('change',()=>{const selected=interventionSelect.value;let item;if(selected.startsWith('sample:')){item=sampleInterventionSites(selectedArea)[Number(selected.slice(7))];if(!item)return}else{const id=selected.startsWith('site:')?selected.slice(5):selected;item=interventions.find(x=>String(x.id)===id);if(!item)return}const location=form.elements.namedItem('location');if(location)location.value=item.location||item.name||'';const lat=$('#photo-lat'),lng=$('#photo-lng');if(lat)lat.value=item.lat??'';if(lng)lng.value=item.lng??''});form.addEventListener('submit',async e=>{e.preventDefault();const f=input.files[0];const fileError=photoFileError(f);if(fileError){show(fileError);return toast(fileError)}if(!form.reportValidity())return;const fd=new FormData(form);fd.delete('watershed');const selectedSite=String(fd.get('intervention_id')||'');fd.set('intervention_id',selectedSite.startsWith('sample:')?'':selectedSite.startsWith('site:')?selectedSite.slice(5):selectedSite);if(submit){submit.disabled=true;submit.textContent='Uploading...'}show('Uploading photo and saving GPS record...');try{const response=await fetch(API+'/photos',{method:'POST',body:fd,credentials:'same-origin'});let result;try{result=await response.json()}catch{throw Error(`Upload failed (${response.status}). The server returned an unreadable response.`)}if(!response.ok)throw Error(result.error||`Upload failed (${response.status}).`);const phase=fd.get('phase');form.reset();$('#preview').innerHTML='';show(`${phase[0].toUpperCase()+phase.slice(1)} photo saved at the selected symbol coordinates. It will appear in that symbol’s details.`,true);toast('Photo saved with its GPS coordinates.');await loadPhotos()}catch(err){show(err.message);toast(err.message)}finally{if(submit){submit.disabled=false;submit.textContent='Upload photo'}}})}
function bindInterventionForm(){const form=$('#intervention-form');if(!form)return;form.addEventListener('submit',async e=>{e.preventDefault();const payload=Object.fromEntries(new FormData(form));try{await api('/interventions',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});await loadInterventions();form.reset();toast('Intervention site saved to Coordinator field records.')}catch(error){toast(error.message)}})}
function previewFile(){let f=$('#photo-file').files[0];if(!f)return;const u=URL.createObjectURL(f);$('#preview').innerHTML=`<img src="${u}" style="display:block;max-width:150px;max-height:70px;object-fit:cover;margin:9px auto;border-radius:5px">`}
async function exportJSON(){if(!selectedArea||!analyticsFeatures)return toast('Select an area and wait for its data before exporting.');const report=buildAreaReport();const blob=new Blob([JSON.stringify(report,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`vasudha-${String(selectedArea.name||'area').toLowerCase().replace(/[^a-z0-9]+/g,'-')}-report.json`;a.click();URL.revokeObjectURL(a.href);toast('Selected area report exported.')}
function buildAreaReport(){const features=analyticsFeatures.features||[],count=layer=>features.filter(f=>f.properties.layer===layer),drain=count('drainage');return {generated_at:new Date().toISOString(),area:{name:selectedArea.name,display_name:selectedArea.display_name,osm_type:selectedArea.osm_type,osm_id:selectedArea.id,geometry:selectedArea.geometry,area_km2:geometryAreaKm2(selectedArea.geometry)},source:{boundary:'OpenStreetMap Nominatim',features:'OpenStreetMap Overpass API',attribution:'OpenStreetMap contributors',limit:1200},summary:{mapped_feature_count:features.length,land_use_count:count('landuse').length,vegetation_tag_count:count('vegetation').length,water_feature_count:count('water-bodies').length,drainage_feature_count:drain.length,drainage_length_km:drain.reduce((n,f)=>n+geometryLengthKm(f.geometry),0)},unavailable:['Soil moisture','Land degradation severity','Satellite vegetation indices','Time-series change','Intervention outcomes'],features}}
